begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to anon,authenticated,service_role;
select no_plan();
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) values
('a0000000-0000-4000-8000-000000000001','admin@privacy.test',now(),'{"nome":"Admin Privacidade","tipo":"sindico","cidade":"São Paulo","estado":"SP","termos":true,"termos_versao":"2026-10-21","privacidade_versao":"2026-10-21"}'),
('a0000000-0000-4000-8000-000000000002','reader@privacy.test',now(),'{"nome":"Nome Pessoal","telefone":"11988887777","tipo":"sindico","cidade":"São Paulo","estado":"SP","termos":true,"termos_versao":"2026-10-21","privacidade_versao":"2026-10-21"}'),
('a0000000-0000-4000-8000-000000000003','other@privacy.test',now(),'{"nome":"Outra Pessoa","tipo":"sindico","cidade":"São Paulo","estado":"SP","termos":true,"termos_versao":"2026-10-21","privacidade_versao":"2026-10-21"}');
insert into public.user_roles(user_id,role) values('a0000000-0000-4000-8000-000000000001','admin');
insert into auth.sessions(id,user_id) values('a1000000-0000-4000-8000-000000000002','a0000000-0000-4000-8000-000000000002');
insert into auth.refresh_tokens(user_id,token) values('a0000000-0000-4000-8000-000000000002','fixture-token');
insert into public.email_log(destinatario,template,assunto,status) values('reader@privacy.test','teste','Assunto pessoal','enviado');
set local role anon;
select throws_ok($$select public.exportar_minha_conta()$$,'42501',null,'anônimo não exporta');
select throws_ok($$select public.anonimizar_conta('a0000000-0000-4000-8000-000000000002')$$,'42501',null,'anônimo não apaga');
reset role;set local role authenticated;
select set_config('request.jwt.claim.sub','a0000000-0000-4000-8000-000000000002',true);
select is(public.exportar_minha_conta()->'conta'->>'nome','Nome Pessoal','exporta os próprios dados');
select ok(position('other@privacy.test' in public.exportar_minha_conta()::text)=0,'não exporta outra conta');
select is(jsonb_array_length(public.exportar_minha_conta()->'consentimentos'),2,'exporta as versões aceitas');
select throws_ok($$select public.anonimizar_conta('a0000000-0000-4000-8000-000000000003')$$,'42501',null,'cliente não pode escolher vítima');
select throws_ok($$select public.limitar_conta(array['a','b'])$$,'42501',null,'cliente não manipula limites');
reset role;set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select ok(public.validar_sessao_conta('a0000000-0000-4000-8000-000000000002','a1000000-0000-4000-8000-000000000002'),'sessão persistida válida');
select ok(not public.validar_sessao_conta('a0000000-0000-4000-8000-000000000003','a1000000-0000-4000-8000-000000000002'),'sessão não serve para outra pessoa');
select ok(public.limitar_conta(array['u','i']),'tentativa 1');
select ok(public.limitar_conta(array['u','i']),'tentativa 2');
select ok(public.limitar_conta(array['u','i']),'tentativa 3');
select ok(public.limitar_conta(array['u','i']),'tentativa 4');
select ok(public.limitar_conta(array['u','i']),'tentativa 5');
select ok(not public.limitar_conta(array['u','i']),'sexta tentativa bloqueada');
select throws_ok($$select public.anonimizar_conta('a0000000-0000-4000-8000-000000000001')$$,'P0001','O último admin ativo não pode ser desativado','protege último admin');
select is(public.anonimizar_conta('a0000000-0000-4000-8000-000000000002')->>'anonimizada','true','anonimização concluída');
select is(public.anonimizar_conta('a0000000-0000-4000-8000-000000000002')->>'anonimizada','true','repetição idempotente');
reset role;
select is((select nome from public.profiles where id='a0000000-0000-4000-8000-000000000002'),'Conta removida','nome removido');
select is((select telefone from public.profiles where id='a0000000-0000-4000-8000-000000000002'),null,'telefone removido');
select ok(not private.has_role('a0000000-0000-4000-8000-000000000002','sindico'),'permissões revogadas');
select is((select count(*) from auth.sessions where user_id='a0000000-0000-4000-8000-000000000002'),0::bigint,'sessões revogadas');
select is((select count(*) from auth.refresh_tokens where user_id='a0000000-0000-4000-8000-000000000002'),0::bigint,'refresh tokens revogados');
select is((select count(*) from public.email_log where destinatario='reader@privacy.test'),0::bigint,'logs pessoais removidos');
select ok(not exists(select 1 from public.audit_log where coalesce(antes::text,'') like '%Nome Pessoal%' or coalesce(depois::text,'') like '%Nome Pessoal%'),'auditoria sem cópias pessoais');
select is((select nome from public.profiles where id='a0000000-0000-4000-8000-000000000003'),'Outra Pessoa','outra conta preservada');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
select throws_ok($$select public.exportar_minha_conta()$$,'P0001','Sessão inválida','JWT antigo sem acesso após apagar');
reset role;
select ok(not exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in('public','private') and c.relkind='r' and not c.relrowsecurity),'nenhuma tabela de aplicação sem RLS');
set local role authenticated;
select throws_ok($$select public.verificar_login('{"user_id":"a0000000-0000-4000-8000-000000000003","valid":true}')$$,'42501',null,'cliente não executa hook de autenticação');
select * from finish();rollback;
